            'order_id': f'order_{int(time.time())}',
            'callback_url': f'{request.host_url}api/webhook',
            'success_url': f'{request.host_url}success',
            'cancel_url': f'{request.host_url}cancel',
            'payment_methods': ['card', 'apple_pay', 'google_pay']
        }

        # API kulcs aláírás
        signature = generate_signature(payment_data, PAYGATE_API_KEY)
        payment_data['signature'] = signature

        headers = {
            'Content-Type': 'application/json',
            'X-API-Key': PAYGATE_API_KEY
        }

        response = requests.post(
            f'{PAYGATE_API_URL}/payments',
            json=payment_data,
            headers=headers
        )

        if response.status_code in [200, 201]:
            result = response.json()
            return jsonify({
                'success': True,
                'payment_id': result.get('payment_id'),
                'payment_url': result.get('payment_url'),
                # Vagy embedded widget token
                'widget_token': result.get('widget_token')
            })
        else:
            return jsonify({
                'success': False,
