    modal.style = 'position:fixed; top:0; left:0; width:100%; height:100%; background:rgba(0,0,0,0.8); z-index:9999;';
    modal.innerHTML = `
        <div style="max-width:500px; height:80%; margin:5% auto; background:white; border-radius:10px; overflow:hidden;">
            <button onclick="this.parentElement.parentElement.remove()" style="position:absolute; right:20px; top:20px; z-index:10000; background:red; color:white; border:none; padding:10px 15px; cursor:pointer; border-radius:5px;">Bezár</button>
            <iframe src="${url}" style="width:100%; height:100%; border:none;"></iframe>
        </div>
    `;
    document.body.appendChild(modal);
}
```

